<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,CentreManagerFollowup as Work};
use App\Support\{CentreManagerAccess as A,CentreOversight as O,CentreFollowups as F};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\Support\{AuditFault,CentreManagerFixture};
use Tests\TestCase;
class CentreFollowupsTest extends TestCase {
 use LazilyRefreshDatabase,CentreManagerFixture;
 public function test_source_linked_creation_uses_current_main_tutor_and_keeps_source_work_unchanged():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$this->assertTrue(F::intact($w));$this->assertSame('Open',$w->status);$this->assertSame($f['tutor']->id,$w->owner_id);$this->assertSame('Draft',$f['task']->fresh()->status);$this->assertStringNotContainsString('PRIVATE-OPERATIONAL-REF49',DB::table('centre_manager_followups')->value('details'));}
 public function test_owner_acknowledges_and_resolves_without_approving_task():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$p=O::position($f['tutor'],$f['a'],'training',$f['from'],$f['to']);F::update($f['tutor'],1,$w,1,'In progress',$p['source_hash'],'Fictional acknowledged source work');$w->refresh();F::update($f['tutor'],1,$w,2,'Resolved',$p['source_hash'],'Fictional source checked and follow-up closed');$this->assertSame('Resolved',$w->fresh()->status);$this->assertNull($w->fresh()->open_key);$this->assertSame('Draft',$f['task']->fresh()->status);}
 public function test_manager_cannot_mark_owner_work_resolved_but_can_cancel_coordination():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$this->actingAs($f['manager'])->postJson('/centre-followups/'.$w->id,['version'=>1,'status'=>'Resolved','source_hash'=>$w->source_hash,'reference'=>'Fictional manager cannot complete source','confirmed'=>1])->assertForbidden();F::update($f['manager'],1,$w,1,'Cancelled',$w->source_hash,'Fictional obsolete request cancellation');$this->assertSame('Cancelled',$w->fresh()->status);}
 public function test_unrelated_staff_cannot_read_or_receive_work():void {$f=$this->f();$this->granted($f);$other=User::factory()->create(['role'=>'tutor']);$p=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$this->reject(fn()=>F::create($f['manager'],1,$f['a'],'training','task_deadline',$f['from'],$f['to'],$p['source_hash'],$other,'tutor',(string)Str::uuid(),today()->addDay()->toDateString(),'Fictional wrong owner'));$w=$this->work($f);$this->actingAs($other)->get('/centre-followups/'.$w->id)->assertNotFound();}
 public function test_read_only_manager_cannot_create_internal_work():void {$f=$this->f();$this->granted($f,['training']);$p=O::position($f['manager'],$f['a'],'training',$f['from'],$f['to']);$this->actingAs($f['manager'])->postJson('/centre-oversight/apprentices/'.$f['a']->id.'/training/follow-up',['flag'=>'task_deadline','from'=>$f['from'],'to'=>$f['to'],'source_hash'=>$p['source_hash'],'owner_choice'=>$f['tutor']->id.':tutor','request_token'=>(string)Str::uuid(),'due'=>today()->addDay()->toDateString(),'reference'=>'Fictional missing coordination permission','confirmed'=>1])->assertForbidden();}
 public function test_source_drift_refuses_creation_and_owner_update():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$p=O::position($f['tutor'],$f['a'],'training',$f['from'],$f['to']);$f['task']->forceFill(['status'=>'Approved','version'=>2])->save();$this->reject(fn()=>F::update($f['tutor'],1,$w,1,'Resolved',$p['source_hash'],'Fictional stale source update'));$q=O::position($f['tutor'],$f['a'],'training',$f['from'],$f['to']);F::update($f['tutor'],1,$w,1,'Resolved',$q['source_hash'],'Fictional actual refreshed source checked');$this->assertSame('Resolved',$w->fresh()->status);}
 public function test_exact_create_replay_returns_same_work_and_duplicate_open_source_is_refused():void {$f=$this->f();$this->granted($f);$token=(string)Str::uuid();$a=$this->work($f,$token);$b=$this->work($f,$token);$this->assertSame($a->id,$b->id);$this->reject(fn()=>$this->work($f));$this->assertDatabaseCount('centre_manager_followups',1);}
 public function test_assignment_transfer_removes_old_owner_from_query_and_direct_view():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$new=User::factory()->create(['role'=>'tutor']);$f['a']->update(['tutor_id'=>$new->id]);$this->assertFalse(F::query($f['tutor'])->exists());$this->assertFalse(F::visible($f['tutor'],$w));$this->actingAs($f['tutor'])->get('/centre-followups/'.$w->id)->assertNotFound();}
 public function test_group_transfer_removes_delegated_manager_from_query_and_direct_view():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$f['a']->update(['tutor_group_id'=>$f['otherGroup']->id]);$this->assertFalse(F::query($f['manager'])->exists());$this->actingAs($f['manager'])->get('/centre-followups/'.$w->id)->assertNotFound();}
 public function test_owner_retains_legitimate_assignment_work_after_requester_grant_revoked():void {$f=$this->f();$g=$this->granted($f);$w=$this->work($f);A::revoke($f['admin'],1,$f['manager'],$g->version,'Fictional requester scope revoked');$this->assertFalse(F::visible($f['manager'],$w));$this->assertTrue(F::visible($f['tutor'],$w));$p=O::position($f['tutor'],$f['a'],'training',$f['from'],$f['to']);F::update($f['tutor'],1,$w,1,'In progress',$p['source_hash'],'Fictional current tutor accepts');$this->assertSame('In progress',$w->fresh()->status);}
 public function test_creation_and_update_audit_failures_roll_back_work():void {$f=$this->f();$this->granted($f);AuditFault::install('centre_work_fault','portal_operations_events','fictional fault','centre_followup_created');try{$this->work($f);$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('centre_manager_followups',0);}
 public function test_update_audit_failure_retains_previous_status_version_and_history():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$p=O::position($f['tutor'],$f['a'],'training',$f['from'],$f['to']);AuditFault::install('centre_update_fault','portal_operations_events','fictional fault','centre_followup_updated');try{F::update($f['tutor'],1,$w,1,'In progress',$p['source_hash'],'Fictional source update');$this->fail('Expected database failure');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Open',$w->fresh()->status);$this->assertSame(1,$w->version);}
 public function test_closed_or_stale_work_cannot_be_overwritten():void {$f=$this->f();$this->granted($f);$w=$this->work($f);F::update($f['manager'],1,$w,1,'Cancelled',$w->source_hash,'Fictional cancelled');$this->reject(fn()=>F::update($f['manager'],1,$w,1,'Cancelled',$w->source_hash,'Fictional stale repeat'));}
 public function test_work_state_tamper_refuses_use():void {$f=$this->f();$this->granted($f);$w=$this->work($f);DB::table('centre_manager_followups')->where('id',$w->id)->update(['status'=>'Resolved']);$this->assertFalse(F::intact($w->fresh()));$this->actingAs($f['manager'])->get('/centre-followups/'.$w->id)->assertConflict();}
 public function test_real_inbox_and_owner_form_have_private_headers_and_explicit_confirmation():void {$f=$this->f();$this->granted($f);$w=$this->work($f);$this->actingAs($f['tutor'])->get('/centre-followups')->assertOk()->assertSee('Open follow-up')->assertHeader('Referrer-Policy','no-referrer');$this->get('/centre-followups/'.$w->id)->assertOk()->assertSee('Responsible staff update');$this->postJson('/centre-followups/'.$w->id,[])->assertUnprocessable();}
 public function test_release_check_remains_read_only_and_not_actual_acceptance():void {$r=\App\Support\Release49Check::report();$this->assertSame('49',$r['pack']);$this->assertFalse($r['writes_performed']);$this->assertFalse($r['actual_target_acceptance']);$this->assertTrue($r['checks']['route:centre-access.apply']);$this->artisan('gta:release-check49')->assertSuccessful();}
}
